    "dailyChecklists": [
      {
        "name": "Morning Truck Dispatch & Safety Briefing",
        "shiftTime": "06:30 AM - 07:30 AM",
        "responsibleRole": "Lead Field Foreman / Fleet Manager",
        "tasks": [
          "Conduct physical walk-around vehicle inspection: tire pressure, fluid levels, turn signals, and ladder racks.",
          "Verify required PPE in each truck: hard hats, safety glasses, high-voltage gloves, and steel-toe boots.",
          "Check that Lockout/Tagout (LOTO) kits, fire extinguishers, and first aid kits are fully stocked.",
          "Conduct 5-minute Tailgate Safety Meeting covering daily hazards (heat, electrical, working at height).",
          "Review assigned route and parts inventory with dispatch supervisor; confirm specialty fittings on truck.",
          "Sign off on digital DOT DVIR (Driver Vehicle Inspection Report) on company mobile tablet."
        ]
      },
      {
        "name": "Mid-Day Job Site Safety & Work-in-Progress Audit",
        "shiftTime": "12:00 PM - 01:00 PM",
        "responsibleRole": "Field Supervisor / Project Manager",
        "tasks": [
          "Verify work area is cordoned off with safety cones or caution tape to prevent customer bystander injury.",
          "Inspect ladder setups for proper 4:1 lean angle and verify 3-foot extension above landing roofline.",
          "Review technician diagnostic notes against initial estimate; identify any necessary change orders.",
          "Confirm customer authorization obtained in writing prior to commencing unauthorized repairs.",
          "Check hydration stations and heat stress prevention compliance during high-temperature conditions.",
          "Audit recovered scrap or replaced warranty components for proper labeling and disposal."
        ]
      },
      {
        "name": "Evening Shop Return, Tool Lockdown & Fleet Staging",
        "shiftTime": "04:30 PM - 05:45 PM",
        "responsibleRole": "Shop Operations Lead & Dispatcher",
        "tasks": [
          "Direct service vans to dedicated parking bays; verify all cab and side doors are locked and alarmed.",
          "Return high-value specialty equipment (thermal imagers, pipe cameras, recovery machines) to tool crib.",
          "Stage restocking inventory boxes for tomorrow morning’s scheduled jobs next to designated technician bays.",
          "Consolidate collected checks and credit card payment batch reports; submit to bookkeeping.",
          "Empty warehouse trash bins, dispose of oily rags in self-closing UL-listed safety cans.",
          "Lock perimeter compound security gates, activate motion floodlights, and set main facility alarm."
        ]
      }
    ]
